static bool polygons_match_with_tolerance(const std::vector<Point>& a,
                                          const std::vector<Point>& b,
                                          double tol = 1e-7) {
    if (a.empty() || b.empty()) {
        return a.empty() && b.empty();
    }
    if (a.size() != b.size()) {
        return false;
    }

    auto same_point = [tol](const Point& lhs, const Point& rhs) {
        return std::abs(CGAL::to_double(lhs.x()) - CGAL::to_double(rhs.x())) <= tol &&
               std::abs(CGAL::to_double(lhs.y()) - CGAL::to_double(rhs.y())) <= tol;
    };

    auto matches_with_start = [&](bool reverse) {
        for (size_t start = 0; start < b.size(); ++start) {
            if (!same_point(a[0], b[start])) {
                continue;
            }
            bool ok = true;
            for (size_t i = 0; i < a.size(); ++i) {
                size_t idx = reverse ? (start + b.size() - i) % b.size()
                                     : (start + i) % b.size();
                if (!same_point(a[i], b[idx])) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return true;
            }
        }
        return false;
    };

    return matches_with_start(false) || matches_with_start(true);
}

